import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';

const VoirCours = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [cours, setCours] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchCourse = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await fetch(`http://localhost:5000/api/courses/${id}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        const result = await response.json();
        setCours(result.data.course);
      } else {
        setError('Cours non trouvé');
      }
    } catch (error) {
      setError('Erreur de chargement');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCourse();
  }, [id]);

  if (loading) return <div>Chargement...</div>;
  if (error) return <div>Erreur: {error}</div>;

  return (
    <div style={{ padding: '20px' }}>
      <button onClick={() => navigate('/mes-cours')} style={{ marginBottom: '20px' }}>
        ← Retour
      </button>
      
      <h1>{cours.title}</h1>
      <p><strong>Description:</strong> {cours.description}</p>
      <p><strong>Niveau:</strong> {cours.level}</p>
      <p><strong>Classe:</strong> {cours.class_name}</p>
      <p><strong>Créé le:</strong> {new Date(cours.created_at).toLocaleDateString()}</p>
      
      {cours.fichier && (
        <div>
          <strong>Fichier:</strong> {cours.fichier}
        </div>
      )}
    </div>
  );
};

export default VoirCours;
